-- ============================================================
-- 启动种子数据(全部 INSERT IGNORE, 幂等): RBAC + 管理员 + 系统配置
-- 已有数据的库自动跳过; 全新库获得可登录的初始账号与菜单权限。
-- ============================================================

-- 系统配置(来自 init_full.sql)

-- 初始用户:仅管理员(演示账号已于 2026-08-21 按产品要求移除,团队成员由 admin 在用户管理中创建)

-- RBAC: 权限/角色/角色权限/用户角色(来自 rbac_data.sql, 跨行语句完整提取)

-- 排期辅助与冲突管控配置(v12)

-- 变更审批人池(可配置): 逗号分隔的用户ID。空=回退角色规则(PM一审+负责人二审)

-- 技术债存量闸门: 项目未偿还债务超过该工时数则禁止启动新迭代(0=关闭闸门)

-- 业务仲裁权限默认授予项目经理(role 6):流程卡死时的兜底裁决人。admin 不再做业务兜底。
-- project_manager 不受 system-data JSON 管辖,此授权可在"角色权限"页面自由改配给产品或其他角色。
SELECT 0,'biz:override','业务仲裁(流程兜底)',2,99,1,NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `sys_permission` WHERE `permission_code`='biz:override');
SELECT r.`id`,p.`id`,NOW() FROM `sys_role` r, `sys_permission` p
WHERE r.`role_code`='project_manager' AND p.`permission_code`='biz:override'
AND NOT EXISTS (SELECT 1 FROM `sys_role_permission` x WHERE x.`role_id`=r.`id` AND x.`permission_id`=p.`id`);

-- 外部匿名工单占位账号:禁用不可登录,仅作外部单 reporter_id 兜底(工单表提报人非空)
